<template><AppShell><AsyncState v-if="state==='loading'" type="loading" title="학습 정보를 불러오고 있어요" description="수강 상태와 차시 정보를 확인하고 있습니다."/><AsyncState v-else-if="state==='error'" type="error" title="학습 정보를 불러오지 못했어요" :description="feedback" @retry="load"/><template v-else><PageHeader eyebrow="Lesson player" :title="lesson.title" :description="`${course.title} · 현재 진도 ${enrollment.progressRate}%`"/><section class="panel player"><div><span class="tag">{{ lesson.required?'필수 차시':'선택 차시' }}</span><h2>{{ lesson.title }}</h2><p>차시 콘텐츠를 학습한 뒤 서버에 시작 또는 완료 상태를 저장하세요.</p></div><p v-if="feedback" role="status">{{ feedback }}</p><div class="actions"><button class="button" :disabled="submitting" @click="start">학습 시작</button><button class="button accent" :disabled="submitting" @click="complete">차시 완료</button></div></section></template></AppShell></template>
<script setup>import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import AppShell from '@/components/AppShell.vue';import PageHeader from '@/components/PageHeader.vue';import AsyncState from '@/components/AsyncState.vue';import{enrollmentApi}from'@/api/enrollment.js';import{courseApi}from'@/api/course.js';const route=useRoute(),state=ref('loading'),feedback=ref(''),submitting=ref(false),enrollment=ref({}),course=ref({}),lesson=ref({});async function load(){state.value='loading';try{enrollment.value=(await enrollmentApi.getById(route.params.enrollmentId)).data.data;const[courseResponse,lessonResponse]=await Promise.all([courseApi.getById(enrollment.value.courseId),courseApi.getLessons(enrollment.value.courseId)]);course.value=courseResponse.data.data;lesson.value=lessonResponse.data.data.find(item=>String(item.lessonId)===String(route.params.lessonId));if(!lesson.value)throw new Error('차시를 찾을 수 없습니다.');state.value='ready'}catch(error){feedback.value=error.response?.data?.message||error.message||'학습 정보를 불러오지 못했습니다.';state.value='error'}}async function action(request,message){submitting.value=true;try{const response=await request();enrollment.value.progressRate=response.data.data.progressRate;feedback.value=message}catch(error){feedback.value=error.response?.data?.message||'학습 상태를 저장하지 못했습니다.'}finally{submitting.value=false}}function start(){return action(()=>enrollmentApi.startLesson(route.params.enrollmentId,route.params.lessonId),'학습 시작 시각을 저장했습니다.')}function complete(){return action(()=>enrollmentApi.completeLesson(route.params.enrollmentId,route.params.lessonId),'차시 완료와 진도율을 저장했습니다.')}onMounted(load)</script>
<style scoped>.player{max-width:760px;margin:auto;padding:34px}.player h2{margin:18px 0 8px}.player p{color:var(--muted);line-height:1.7}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:28px}</style>
